window.DE_CHUNKS=window.DE_CHUNKS||[];window.DE_CHUNKS.push([{"id":521,"unit":5,"q":"Design Binary Parallel Adder for addition of two binary numbers A= 1010 and B= 1110","k":"","s":["Write the required truth table or Boolean expression.","Simplify it with Boolean algebra or a K-map where appropriate.","Draw the labelled gate-level circuit from the simplified equation."]},{"id":522,"unit":5,"q":"Design 4-Bit BCD adder which perform BCD addition of two decimal number 5 and 7.","k":"","s":["Add the two valid BCD digits with a 4-bit binary adder.","Correction condition: K = Cout + S3S2 + S3S1. If K=1, add 0110 to the first sum.","The corrected lower nibble is the units BCD digit and the carry is the tens digit."]},{"id":523,"unit":5,"q":"Design Logic diagram of Full adder and Full Subtractor with the help of truth table and logical equation.","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":524,"unit":5,"q":"How many full adders are needed to add 4-bit numbers A and B with a Serial adder?","k":"A","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":525,"unit":5,"q":"which of the following statement/s are true , I) In combinational circuits, memory are used for store the previous input so output of combinational circuits is depends on present as well as previous inputs. II) for n bit additions of binary number, number of full adder required for these is (n-1)n III) In full adder & full subtractor , there is similarity of sum bit (s) in case of full adder & borrow bit (bin) in case of full subtractor. IV) In output of BCD adder has range for sum output in 00000 to 10001.","k":"D","s":["Add the two valid BCD digits with a 4-bit binary adder.","Correction condition: K = Cout + S3S2 + S3S1. If K=1, add 0110 to the first sum.","The corrected lower nibble is the units BCD digit and the carry is the tens digit."]},{"id":526,"unit":5,"q":"Illustrate the adder circuit which adds two 4 bit numbers which are (3)BCD & (9)BCD through BCD addition & obtain the answer in BCD form.","k":"","s":["Decimal addition: 3 + 9 = 12.","BCD result = 0001 0010.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":527,"unit":5,"q":"Design truth table and give Boolean function for Full Subtractor. Write the simplified Boolean functions for its outputs and implement it with NOR gates only.","k":"","s":["Difference: D=A⊕B⊕Bin.","Borrow: Bout=A'B + A'Bin + B·Bin.","These equations come directly from the 8-row full-subtractor truth table."]},{"id":528,"unit":5,"q":"Illustrate the Addition of (15)10 & (7)10 By using binary adders of which requires an n-full adder for n-bit addition. (with logic diagram)","k":"","s":["For inputs A, B and Cin: S=A⊕B⊕Cin.","Carry: Cout=AB+ACin+BCin = AB+Cin(A⊕B).","Use the 8-row truth table and implement these two equations."]},{"id":529,"unit":5,"q":"Illustrate the combinational circuits that subtracts one bit from another one bit, when already there is a borrow from this column for subtraction in preceding column, and outputs the difference bit and borrow bit along with truth table, Boolean function & logic circuit diagram.","k":"","s":["Write the required truth table or Boolean expression.","Simplify it with Boolean algebra or a K-map where appropriate.","Draw the labelled gate-level circuit from the simplified equation."]},{"id":530,"unit":5,"q":"Which statement/s is/are true? 1) A half adder is also known as XNOR gate because XNOR is applied to both inputs to produce the sum. 2) Half adder can add only two bits (A and B) and has nothing to do with the carry. 3) If the input to a half adder has a carry, then it will neglect it and adds only the A and B bits that means the binary addition process is not complete and that’s way it is called a half adder. 4) A half adder is a two input and two output combinational circuit.","k":"B","s":["Half-adder: Sum=A⊕B, Carry=AB.","Truth table (A,B → S,C): 00→00, 01→10, 10→10, 11→01."]},{"id":531,"unit":5,"q":"Design the digital circuit that adds (8)BCD digit with (5)BCD digit in parallel and produces a sum digit also in BCD.","k":"","s":["Decimal addition: 8 + 5 = 13.","BCD result = 0001 0011.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":532,"unit":5,"q":"Design the digital circuit that adds (7)BCD with (7)BCD in parallel and produces a sum digit also in BCD format. Show the appropriate circuit diagram and steps that describe the BCD addition process","k":"","s":["Decimal addition: 7 + 7 = 14.","BCD result = 0001 0100.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":533,"unit":5,"q":"Design a 4-bit parallel adder to find the sum and output carry for the addition of the following two 4-bit numbers which are A0A1A2A3 = 1011 and B0B1B2B3 = 1111 and the input carry (C0) is 0. List bitwise sum and output carry for the 4-bit parallel adder.","k":"","s":["Write the required truth table or Boolean expression.","Simplify it with Boolean algebra or a K-map where appropriate.","Draw the labelled gate-level circuit from the simplified equation."]},{"id":534,"unit":5,"q":"Design the digital circuit that adds (7)BCD with (9)BCD in parallel and produces a sum digit also in BCD format. Show the appropriate circuit diagram and steps that describe the BCD addition process.","k":"","s":["Decimal addition: 7 + 9 = 16.","BCD result = 0001 0110.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":535,"unit":5,"q":"Design a combinational circuit that generates BCD sum of (3)BCD and (9)BCD number with necessary equations and truth table.","k":"","s":["Decimal addition: 3 + 9 = 12.","BCD result = 0001 0010.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":536,"unit":5,"q":"Design a combinational circuit that add (9)BCD and (8)BCD number with necessary equations.","k":"","s":["Decimal addition: 9 + 8 = 17.","BCD result = 0001 0111.","If the first 4-bit sum is greater than 1001 or Cout=1, add 0110 to correct it to BCD."]},{"id":537,"unit":5,"q":"Prove that a full adder can be obtained by two half adder and an OR gate.","k":"","s":["Half adder 1: S1=A⊕B, C1=AB.","Half adder 2: S=S1⊕Cin, C2=S1·Cin.","Cout=C1+C2=AB+Cin(A⊕B).","Thus two half adders and one OR gate form a full adder."]}]);